import {MODE_DESCRIPTIONS} from './difficulty.js';
import {LESSONS,MODES,studyTime,turnGuide,objectiveFor} from './learning.js';
import {GAMES,TYPES,SOURCE} from './data.js';
import {esc,btn,log} from './core.js';
import {virus,race,number,zoo,grass,equation} from './main-games.js';
import {puzzle,memory,words,scale,montage,three} from './prize-games.js';
import {morris,hex,gomoku} from './final-games.js';
import {art,sigil,logo} from './art.js';
const ENGINES={virus,race,number,zoo,grass,equation,puzzle,memory,words,scale,montage,three,morris,hex,gomoku};
const STORE='devils-plan.local.v1';
const defaults=()=>({version:1,settings:{difficulty:'relaxed',studySeconds:30,seed:''},results:[],active:null});
let profile;try{let p=JSON.parse(localStorage.getItem(STORE));profile=p?.version===1&&Array.isArray(p.results)&&p.settings?{...defaults(),...p}:defaults();if(profile.active&&!ENGINES[profile.active.id])profile.active=null;}catch{profile=defaults();}
profile.sessions=profile.sessions||{};if(profile.active&&profile.active.rulesVersion!==3){profile.legacyActive=profile.active;profile.active=null;}
if(profile.active?.id==='puzzle'&&profile.active.puzzleEdition!==2){profile.legacyPuzzle=profile.active;profile.active=null;}
let briefingId=null,undoState=null;
let filter='all',day=null,screen='library',storageWarned=false;
const root=document.getElementById('app'),modal=document.getElementById('modal');
function save(){try{if(profile.active?.rulesVersion===3)localStorage.setItem(STORE+'.session.'+profile.active.id,JSON.stringify(profile.active));localStorage.setItem(STORE,JSON.stringify(profile));}catch{if(!storageWarned){toast('Browser storage is unavailable. Keep this tab open to retain progress.');storageWarned=true;}}}
function toast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),4000);}
const completed=()=>new Set(profile.results.filter(r=>r.win&&!r.practice).map(r=>r.id));
const pieces=()=>profile.results.reduce((sum,r)=>sum+(r.win&&!r.practice?GAMES.find(g=>g.id===r.id)?.reward||0:0),0);
const nextGame=()=>GAMES.find(g=>g.type!=='bonus'&&!completed().has(g.id))||GAMES[0];
function sidebar(){return `<aside class="sidebar"><button class="brand" data-ui="home">${logo}<span>THE DEVIL’S<br>PLAN<small>THE GAME ROOM</small></span></button><div class="side-divider"></div><span class="side-label">YOUR INVITATION</span><button class="side-nav ${screen==='library'&&day===null?'active':''}" data-ui="home"><span>▦</span>The game room<span class="nav-arrow">↗</span></button><button class="side-nav" data-ui="rules"><span>▤</span>The rulebook</button><button class="side-nav ${screen==='lab'?'active':''}" data-ui="lab"><span>⚒</span>The laboratory</button><div class="side-divider"></div><span class="side-label">SEASON ONE</span><div class="day-nav">${range(7).map(i=>`<button data-ui="day" data-value="${i+1}" class="${day===i+1?'active':''}"><span>0${i+1}</span>${i===6?'The final':'Day '+(i+1)}<i class="${GAMES.filter(g=>g.day===i+1).every(g=>completed().has(g.id))?'done':''}"></i></button>`).join('')}</div><button class="secret-link" data-ui="bonus">◇<span>The secret chamber</span>↗</button><div class="side-bottom"><div class="local-indicator"><i></i>RUNS IN YOUR BROWSER</div><p>Trust your instincts.<br>Question everything else.</p><button data-ui="settings" class="profile-button"><span class="profile-avatar">Y</span><span>You<small>Solo strategist</small></span><span>⚙</span></button></div></aside>`;}
function range(n){return Array.from({length:n},(_,i)=>i);}
function topbar(){return `<header class="topbar"><div class="breadcrumb">THE GAME ROOM <span>/</span> SEASON 01</div><div class="top-actions"><div class="mode-switch" role="group" aria-label="Difficulty for new games"><span>NEW GAMES</span>${Object.entries(MODES).map(([key,label])=>`<button data-ui="global-mode" data-value="${key}" aria-pressed="${profile.settings.difficulty===key}" class="${profile.settings.difficulty===key?'selected':''}">${label}</button>`).join('')}</div><span class="solo-pill"><i></i>Single player</span><button class="icon-button" data-ui="settings" aria-label="Open settings">⚙</button></div></header>`;}
function shell(content){root.innerHTML=`${sidebar()}<div class="page">${topbar()}${content}<footer><span>AN UNOFFICIAL FAN-MADE STRATEGY ARCADE</span><button data-ui="about">About & sources ↗</button><span>DIFFICULTY EDITION · v3.0</span></footer></div>`;}
function library(){pauseActive();let cleared=completed(),next=nextGame();let shown=GAMES.filter(g=>(day===null||g.day===day)&&(filter==='all'||g.type===filter));shell(`<main class="lobby"><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="red-line"></span>FIFTEEN GAMES. ONE MIND.</div><h1>Every piece<br>has a <em>purpose.</em></h1><p>Step into the world of The Devil’s Plan.<br>Outthink the room. Find your own way to win.</p><button class="btn primary" data-ui="${profile.active?'resume':'start'}" data-value="${next.id}">${profile.active?'Resume your match':'Enter the game room'}<span>↗</span></button><span class="hero-caption">SEASON 01 <i>•</i> YOU VS. THE COMPUTER</span></div><div class="hero-art">${sigil()}<span class="orbit-label top">STRATEGY / INSTINCT / MEMORY</span><span class="hero-art-label">THE PIECE<br><small>ONE MOVE CAN CHANGE EVERYTHING.</small></span><span class="artifact-number">NO. 001</span></div></section><section class="stats-strip" aria-label="Your progress"><div><span class="stat-icon">◇</span><span><strong>${pieces().toString().padStart(2,'0')}</strong><small>Pieces earned</small></span></div><div><span class="stat-icon">▱</span><span><strong>${cleared.size.toString().padStart(2,'0')} <em>/ 15</em></strong><small>Games mastered</small></span></div><div><span class="stat-icon">◎</span><span><strong>${profile.results.length.toString().padStart(2,'0')}</strong><small>Matches played</small></span></div><div class="stat-session"><span class="live-dot"></span><span><strong>Your own pace.</strong><small>Progress saved on this device</small></span></div></section><section class="collection"><div class="collection-heading"><div><span class="eyebrow">CHOOSE YOUR NEXT MOVE</span><h2>${day!==null?(day===0?'The secret chamber':day===7?'The final':'Day '+day):'The collection'}<span>${shown.length.toString().padStart(2,'0')}</span></h2></div><button class="text-button" data-ui="rules">Learn the rules <span>↗</span></button></div><div class="filter-bar">${[['all','All games'],['main','Main matches'],['prize','Prize matches'],['final','The final'],['bonus','Secret chamber']].map(([v,label])=>`<button data-ui="filter" data-value="${v}" class="${filter===v?'active':''}">${label}</button>`).join('')}<span>SOLO ADAPTATIONS</span></div><div class="game-grid">${shown.map((g,i)=>`<button class="game-card ${g.id==='virus'?'featured-card':''}" data-ui="start" data-value="${g.id}"><div class="card-art">${art(g.id)}<span class="card-number">${String(GAMES.indexOf(g)+1).padStart(2,'0')}</span>${cleared.has(g.id)?'<span class="cleared-tag">✓ MASTERED</span>':''}<span class="card-open">↗</span></div><div class="card-copy"><div class="card-meta"><span>${g.day===0?'HIDDEN MATCH':g.day===7?'FINAL MATCH':'DAY 0'+g.day+' / '+(g.type==='main'?'MAIN':'PRIZE')}</span><small>${g.time}</small></div><h3>${g.name}</h3><p>${g.desc}</p><div class="card-bottom"><span>${g.tag}</span><span>${g.type==='prize'?'COOPERATE':'COMPETE'} <b>→</b></span></div></div></button>`).join('')||'<div class="empty-state">No matches of this type on this day. Choose All games.</div>'}</div></section><div class="lobby-note"><span>◇</span><p>Familiar games. A new way to play.<small>Solo versions preserve the central puzzles, with shorter sessions and computer players. Open any rule sheet for the exact adaptations.</small></p><button data-ui="about" class="text-button">Read the approach ↗</button></div></main>`);}
function fields(){let p={};document.querySelectorAll('.game-stage input,.game-stage select').forEach(el=>p[el.id]=el.value);return p;}
function stageKey(s){return [s.round,s.hand,s.phase].join('|');}
function render(){if(briefingId){briefing(briefingId);return;}if(profile.active){game();return;}if(screen==='lab')lab();else library();}
function game(){if(!profile.active.awaitingRound)resumeActive();let s=profile.active,g=GAMES.find(g=>g.id===s.id),engine=ENGINES[s.id];let guide=turnGuide(s);if(s.awaitingRound)guide={text:'Review what changed, then begin the next round.',steps:guide.steps,index:-1};let activeIndex=GAMES.indexOf(g),next=GAMES[activeIndex+1]||GAMES[0];shell(`<main class="game-page"><div class="game-heading"><button class="text-button" data-ui="leave">← The collection</button><div class="game-heading-tools"><span class="seed-label">SEED ${s.initialSeed}</span><button class="text-button" data-ui="game-rules">Rule sheet ↗</button></div></div><div class="match-title"><div><span class="eyebrow">${g.day?'DAY 0'+g.day:'HIDDEN MATCH'} / ${TYPES[g.type].toUpperCase()}</span><h1>${g.name}</h1></div><span class="match-mode">${MODES[s.difficulty]} <i>•</i> ${s.outcome?'COMPLETED':'IN PLAY'}</span></div>${!s.outcome?`<section class="turn-coach" aria-label="Turn guidance"><div><span class="eyebrow">YOUR NEXT MOVE</span><h2>${esc(guide.text)}</h2><ol>${guide.steps.map((x,i)=>`<li class="${i===guide.index?'current':''}">${esc(x)}</li>`).join('')}</ol></div><div class="coach-tools"><button class="btn" data-ui="lesson">Worked example</button>${s.difficulty==='relaxed'?`<button class="btn" data-ui="undo" ${!undoState?'disabled':''}>Undo last action</button>`:''}<button class="text-button" data-ui="test-link">Copy test link ↗</button><button class="text-button" data-ui="feedback">Give feedback ↗</button></div></section>`:''}<div class="game-layout"><section class="game-stage ${s.outcome?'completed':''}" aria-label="Game board">${s.outcome?`<div class="result-banner ${s.outcome.win?'won':''}" role="status"><span class="eyebrow">${s.outcome.score==='Draw'?'DRAW':s.outcome.win?'MATCH WON':'MATCH COMPLETE'}</span><h2>${esc(s.outcome.title)}</h2><p>${esc(s.outcome.detail)}</p><div class="controls"><button class="btn primary" data-ui="replay">Play again ↻</button><button class="btn" data-ui="next" data-value="${next.id}">Next game →</button><button class="btn" data-ui="feedback">Give feedback</button><button class="btn" data-ui="leave">Collection</button></div></div>`:''}<div class="engine-board ${s.outcome?'finished-board':''}">${s.awaitingRound&&!s.outcome?`<div class="round-gate"><span class="eyebrow">ROUND COMPLETE</span><h2>Ready for the next ${s.id==='equation'?'hand':'round'}?</h2><p>${esc(s.logs[0]||'Your next board is ready.')}</p><button class="btn primary" data-ui="begin-round">Begin ${s.hand||s.round} →</button></div>`:engine.view(s)}</div>${s.message?`<div class="game-error" role="alert">${esc(s.message)}</div>`:''}</section><aside class="match-aside">${s.logs.length?`<section class="change-card"><span class="eyebrow">WHAT CHANGED</span><p aria-live="polite">${esc(s.logs[0])}</p></section>`:''}<section class="mission-card"><div class="eyebrow"><span class="live-dot"></span>YOUR OBJECTIVE</div><h3>${objectiveFor(g,s.difficulty)}</h3><p>${LESSONS[s.id].modes[s.difficulty==='relaxed'?0:s.difficulty==='hard'?2:1]}</p><div class="mission-reward"><span>${s.difficulty==='relaxed'?'LEARNING SESSION':'WIN REWARD'}</span><b>${s.difficulty==='relaxed'?'Practice · no pieces':'◇ '+g.reward+' pieces'}</b></div><button class="text-button" data-ui="game-rules">Rules & solo changes ↗</button></section><section class="match-log"><div class="eyebrow">THE DEALER’S LOG</div><ol aria-live="polite">${s.logs.slice(0,12).map((l,i)=>`<li><span>${String(s.logs.length-i).padStart(2,'0')}</span>${esc(l)}</li>`).join('')||'<li>The board is ready. Make your first move.</li>'}</ol></section><button class="text-button" data-ui="restart">Restart this seed ↻</button><p class="save-note">${s.outcome?'Result saved.':'This match autosaves after each move.'}<br>Computer moves run in your browser.</p></aside></div></main>`);
if(!s.outcome)for(let [id,value] of Object.entries(s.drafts||{})){let el=document.getElementById(id);if(el)el.value=value;}
}
function start(id,reuseSeed){let g=GAMES.find(g=>g.id===id);if(!g)return;let seed=reuseSeed??(profile.settings.seed!==''?Number(profile.settings.seed):crypto.getRandomValues(new Uint32Array(1))[0]);seed=seed>>>0;briefingId=null;undoState=null;let difficulty=profile.settings.difficulty;let s={id,rulesVersion:3,seed,initialSeed:seed,difficulty,studySeconds:studyTime(id,difficulty),logs:[],drafts:{},outcome:null,message:'',recorded:false};ENGINES[id].create(s);profile.active=s;history.replaceState({},'',testLink(s));save();render();window.scrollTo({top:0});}
function takeAction(a,v){let s=profile.active;if(!s||s.outcome)return;if(s.awaitingRound)return;let before=JSON.parse(JSON.stringify(s));before.drafts={...s.drafts,...fields()};let oldRound=s.round,oldHand=s.hand;let p=fields(),key=stageKey(s);s.drafts={...s.drafts,...p};s.message='';ENGINES[s.id].act(s,a,v,p);if(!s.message)undoState=before;if(key!==stageKey(s))s.drafts={};if(!s.outcome&&(s.round!==oldRound||s.hand!==oldHand)){s.awaitingRound=true;pauseActive();}settle();}
function settle(){let s=profile.active;if(!s)return;if(s.outcome&&!s.recorded){s.recorded=true;profile.results.push({id:s.id,practice:s.difficulty==='relaxed',win:s.outcome.win,score:s.outcome.score,seed:s.initialSeed,date:new Date().toISOString()});}save();render();}
function pauseActive(){let s=profile.active;if(s&&!s.outcome&&s.deadline&&!s.pausedAt){s.pausedAt=Date.now();save();}}
function resumeActive(){let s=profile.active;if(s?.pausedAt){s.deadline+=Date.now()-s.pausedAt;delete s.pausedAt;save();}}
function openModal(html){pauseActive();modal.innerHTML=`<button class="dialog-close icon-button" data-ui="close" aria-label="Close dialog">×</button>${html}`;if(!modal.open)modal.showModal();}
function settings(){openModal(`<span class="eyebrow">MAKE IT YOUR GAME</span><h2>The control room</h2><p>Your selected difficulty applies across the entire collection when you start a new match. Your current match keeps its own settings.</p><form id="settings-form"><label class="field">Default session mode<select name="difficulty">${['relaxed','standard','hard'].map(v=>`<option value="${v}" ${profile.settings.difficulty===v?'selected':''}>${MODES[v]}</option>`).join('')}</select><small>Each game explains its exact mode changes before you start.</small></label><p class="save-note">Study time follows each game’s mode: Easy is untimed; Standard gives Memory 90 seconds and Hexagon 60; Hard gives 30.</p><label class="field">Replay seed (optional)<input type="number" name="seed" min="0" max="4294967295" step="1" placeholder="Random each match" value="${profile.settings.seed}"><small>The same seed and settings reproduce the same starting board and bot choices for the same actions.</small></label><button type="submit" class="btn primary">Save settings →</button></form>`);}
function ruleSheet(g){return `<div class="rule-sheet"><span class="eyebrow">${TYPES[g.type].toUpperCase()} / ${g.day?'DAY '+g.day:'BONUS'}</span><h2>${g.name}</h2><h3>Core mechanic</h3><ul>${g.rules.map(r=>`<li>${r}</li>`).join('')}</ul><h3>This solo edition</h3><p>${g.adapt}</p><h3>Controls</h3><p>${g.how}</p><h3>Difficulty changes</h3><ul>${LESSONS[g.id].modes.map((text,i)=>`<li><b>${Object.values(MODES)[i]}:</b> ${text}</li>`).join('')}</ul><a class="text-button" href="${SOURCE(g.day||6)}" target="_blank" rel="noopener">Reference · ${g.day||6}일차 ↗</a></div>`;}
function rules(id){let g=GAMES.find(g=>g.id===id)||GAMES[0];openModal(`<div class="rulebook-picker"><label class="field">SELECT A MATCH<select id="rule-game">${GAMES.map(x=>`<option value="${x.id}" ${g.id===x.id?'selected':''}>${x.name}</option>`).join('')}</select></label></div>${ruleSheet(g)}`);}
function about(){openModal(`<span class="eyebrow">DIFFICULTY EDITION / v3.0</span><h2>A seat at the table.</h2><p>A single-player fan project inspired by season one of The Devil’s Plan. All fifteen broadcast-played challenges, including the hidden chamber, are represented here as standalone solo games.</p><p>This is an adaptation arcade, not an exact simulation of the television season. It has no season eliminations, prison assignments, free-form negotiations, human multiplayer, cash prizes or language-model players. Computer opponents use local game-specific logic.</p><p>Dice Poker is excluded: it was not played in the season and its complete rules were not shown. Artwork and puzzle content here are original; no show footage, cast likenesses, music or logos are included.</p><h3>Rule references</h3><p>The supplied English Namu page was inaccessible during research. The Korean mirror’s daily rule sections were consulted, with the season overview as a cross-check. Individual match sheets distinguish preserved mechanics from local changes.</p><div class="source-links">${range(7).map(i=>`<a href="${SOURCE(i+1)}" target="_blank" rel="noopener">Day ${i+1} · Namu mirror ↗</a>`).join('')}<a href="https://en.wikipedia.org/wiki/The_Devil%27s_Plan#Gameplay" target="_blank" rel="noopener">Season overview ↗</a></div><h3>Your data stays here</h3><p>Settings, results and separate game saves are stored in this browser’s local storage. Export them in the laboratory. A different browser, port or private window has separate progress.</p><p class="muted">Unofficial. Not affiliated with Netflix or TEO. Easy sessions do not earn mastery or pieces; scored repeat wins earn more pieces.</p>`);}
function lab(){pauseActive();shell(`<main class="lab-page"><span class="eyebrow">EXPERIMENT. REPLAY. REFINE.</span><h1>The laboratory</h1><p class="page-intro">A place to make the game your own.</p><div class="lab-grid"><section class="lab-card"><span class="lab-number">01</span><h2>Change the conditions.</h2><p>Choose a session mode and replay seed. Each game explains its own timing and computer behavior. Every random board and decision is reproducible.</p><button class="btn primary" data-ui="settings">Open settings ↗</button></section><section class="lab-card"><span class="lab-number">02</span><h2>Take your progress with you.</h2><p>Export a JSON backup of settings, match history and the active board. Import restores settings and results; live boards resume only in their original browser.</p><div class="controls"><button class="btn" data-ui="export">Export progress ↓</button><label class="btn file-button">Import backup ↑<input id="import-file" type="file" accept="application/json,.json"></label></div></section><section class="lab-card"><span class="lab-number">03</span><h2>Look under the board.</h2><p>No build step. No framework. No remote AI. Edit the files in <code>dist/js/</code>, then refresh. Game rules live in three clearly named modules.</p><p><code>main-games.js</code> · main matches<br><code>prize-games.js</code> · cooperative puzzles<br><code>final-games.js</code> · board games</p></section><section class="lab-card"><span class="lab-number">04</span><h2>A clean slate.</h2><p>Remove saved results and the current match. Settings are preserved. Export a backup first if you want to keep them.</p><button class="btn" data-ui="reset">Reset local progress</button></section></div><section class="history-section"><h2>Your match history <span>${profile.results.length}</span></h2>${profile.results.length?`<div class="history-table"><div class="history-row heading"><span>GAME</span><span>RESULT</span><span>SEED</span><span>PLAYED</span></div>${profile.results.slice().reverse().slice(0,30).map(r=>`<div class="history-row"><b>${GAMES.find(g=>g.id===r.id)?.name||'Unknown'}</b><span class="${r.win?'text-green':''}">${r.win?(r.practice?'Practice complete':'Won'):r.score==='Draw'?'Draw':'Completed'}</span><code>${r.seed}</code><span>${new Date(r.date).toLocaleDateString()}</span></div>`).join('')}</div>`:'<p class="muted">Your first match is waiting.</p>'}</section></main>`);}
function leave(){history.pushState({},'','/');pauseActive();save();briefingId=null;screen='library';save();library();window.scrollTo({top:0});}
document.addEventListener('click',e=>{let action=e.target.closest('[data-act]');if(action&&!modal.open){takeAction(action.dataset.act,action.dataset.value);return;}let el=e.target.closest('[data-ui]');if(!el)return;let a=el.dataset.ui,v=el.dataset.value;if(handleLearningAction(a,v))return;if(a==='close'){modal.close();return;}if(a==='settings'){settings();return;}if(a==='rules'){rules();return;}if(a==='game-rules'){rules(profile.active?.id);return;}if(a==='about'){about();return;}if(a==='start'){openBriefing(v);return;}if(a==='replace'||a==='next'){modal.close();openBriefing(v);return;}if(a==='resume'){modal.close();briefingId=null;render();return;}if(a==='leave'){openModal(`<span class="eyebrow">THE COLLECTION</span><h2>Your next move.</h2><p>${profile.active?.outcome?'Your result is saved.':'Every game keeps its own saved board. You can try another game and return later.'}</p><button class="btn primary" data-ui="browse">Browse games →</button>`);return;}if(a==='browse'){modal.close();leave();window.scrollTo({top:0});return;}if(a==='home'||a==='lab'||a==='day'||a==='bonus'||a==='filter'){pauseActive();save();history.replaceState({},'','/');briefingId=null;if(a==='home'){screen='library';day=null;filter='all';}if(a==='lab')screen='lab';if(a==='day'){screen='library';day=+v;filter='all';}if(a==='bonus'){screen='library';day=0;filter='all';}if(a==='filter'){filter=v;day=null;screen='library';}if(screen==='lab')lab();else library();return;}if(a==='replay'){start(profile.active.id);return;}if(a==='restart'){let s=profile.active;openModal(`<span class="eyebrow">RESTART THIS BOARD</span><h2>A different approach?</h2><p>This restarts the current seed from the beginning. The unfinished board will be replaced.</p><button class="btn primary" data-ui="restart-confirm">Restart seed ${s.initialSeed} ↻</button>`);return;}if(a==='restart-confirm'){let s=profile.active;modal.close();let previous={...profile.settings};profile.settings={...profile.settings,difficulty:s.difficulty,studySeconds:s.studySeconds};start(s.id,s.initialSeed);profile.settings=previous;save();return;}if(a==='export'){let blob=new Blob([JSON.stringify(profile,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='devils-plan-progress.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress exported.');return;}if(a==='reset'){openModal(`<span class="eyebrow">RESET PROGRESS</span><h2>Start from zero?</h2><p>This removes your results and active board from this browser. Your settings stay saved.</p><button class="btn danger" data-ui="reset-confirm">Clear local progress</button>`);return;}if(a==='reset-confirm'){for(let g of GAMES)localStorage.removeItem(STORE+'.session.'+g.id);profile.legacyActive=null;profile.results=[];profile.active=null;save();modal.close();lab();toast('Progress cleared.');}});
document.addEventListener('input',e=>{if(e.target.name==='studySeconds')document.getElementById('study-value').textContent=e.target.value+'s';if(e.target.closest('.game-stage')){let s=profile.active;if(s){s.drafts={...s.drafts,[e.target.id]:e.target.value};save();}}});
document.addEventListener('change',async e=>{if(e.target.id==='rule-game'){rules(e.target.value);return;}if(e.target.closest('.game-stage')&&profile.active?.id==='equation'&&e.target.tagName==='SELECT')takeAction('ops','');if(e.target.id==='import-file'){let file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw new Error('Backup is too large.');let p=JSON.parse(await file.text());if(p.version!==1||!Array.isArray(p.results)||!p.settings||!['relaxed','standard','hard'].includes(p.settings.difficulty)||!Number.isFinite(p.settings.studySeconds)||p.settings.studySeconds<10||p.settings.studySeconds>90)throw new Error('Invalid backup format.');if(p.settings.seed!==''&&(!Number.isInteger(p.settings.seed)||p.settings.seed<0||p.settings.seed>4294967295))throw new Error('Invalid replay seed.');if(p.results.some(r=>!GAMES.some(g=>g.id===r.id)||typeof r.win!=='boolean'||!Number.isFinite(r.seed)||!Number.isFinite(Date.parse(r.date))))throw new Error('Invalid match results.');p.active=null;profile=p;save();lab();toast('Settings and results imported. Active boards are not imported for data integrity.');}catch(err){toast('Could not import: '+err.message);}}});
document.addEventListener('submit',e=>{if(e.target.id==='settings-form'){e.preventDefault();let data=new FormData(e.target),seed=data.get('seed');profile.settings={difficulty:data.get('difficulty'),studySeconds:30,seed:seed===''?'':Number(seed)};save();modal.close();toast('Settings saved for new matches.');}else if(e.target.closest('.game-stage'))e.preventDefault();});
document.addEventListener('keydown',e=>{if(modal.open)return;if(e.code==='Space'&&profile.active?.id==='montage'&&profile.active.phase==='watch'&&!['INPUT','TEXTAREA','SELECT','BUTTON'].includes(e.target.tagName)){e.preventDefault();takeAction('buzz','');}if(e.key==='Enter'&&e.target.id==='word'){e.preventDefault();takeAction('word','');}});
setInterval(()=>{let s=profile.active;if(!s||s.outcome||s.awaitingRound||document.hidden||modal.open||!document.querySelector('.game-stage'))return;let e=ENGINES[s.id];let oldRound=s.round;if(e.tick?.(s)){s.drafts={};if(!s.outcome&&s.round!==oldRound){s.awaitingRound=true;pauseActive();}settle();return;}document.querySelectorAll('[data-countdown]').forEach(el=>el.textContent=Math.max(0,Math.ceil((s.deadline-Date.now())/1000))+'s');},200);
// Piece previews use the same placement validator as the game engine.
import {grassLegal} from './main-games.js';import {transform} from './core.js';
document.addEventListener('mouseover',e=>{let s=profile.active;if(s?.id!=='grass'||s.outcome)return;let c=e.target.closest('.grass-board .cell');document.querySelectorAll('.preview-cell,.invalid-cell').forEach(x=>x.classList.remove('preview-cell','invalid-cell'));if(!c)return;let cells=grassLegal(s.board,12,1,transform(s.offers[s.selected],s.rot,s.flip),+c.dataset.value);if(cells)for(let i of cells)document.querySelector(`.grass-board [data-value="${i}"]`)?.classList.add('preview-cell');else c.classList.add('invalid-cell');});
modal.addEventListener('close',()=>{if(document.querySelector('.game-stage')&&!profile.active?.awaitingRound)resumeActive();});
modal.addEventListener('click',e=>{if(e.target===modal){let r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
loadRoute();

function openBriefing(id,push=true){if(!ENGINES[id])return;pauseActive();save();briefingId=id;let mode=profile.settings.difficulty;if(push)history.pushState({},'',`?game=${id}&mode=${mode}`);briefing(id);window.scrollTo({top:0});}
function briefing(id){let g=GAMES.find(g=>g.id===id),l=LESSONS[id];let saved;try{saved=JSON.parse(localStorage.getItem(STORE+'.session.'+id));}catch{}shell(`<main class="game-page briefing"><button class="text-button" data-ui="browse">← The collection</button><span class="eyebrow">STANDALONE GAME / SEASON ONE</span><h1>${g.name}</h1><p class="page-intro">${objectiveFor(g,profile.settings.difficulty)}</p><section class="brief-grid"><div><h2>How a turn works</h2><ol class="brief-steps">${l.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="worked-example"><span class="eyebrow">WORKED EXAMPLE</span><p>${esc(l.example)}</p></div><p>${esc(l.warning)}</p></div><div><h2>Choose your session</h2><p class="save-note">${MODE_DESCRIPTIONS[profile.settings.difficulty]}</p><div class="mode-cards">${Object.entries(MODES).map(([key,label],i)=>`<button class="mode-card ${profile.settings.difficulty===key?'selected':''}" data-ui="choose-mode" data-value="${key}"><b>${label}</b><span>${esc(l.modes[i])}</span></button>`).join('')}</div><p class="save-note">Easy sessions simplify the task and include undo. They do not earn mastery or pieces. The difficulty selector applies to every new game. Each game autosaves separately.</p><div class="controls"><button class="btn primary" data-ui="begin-game" data-value="${id}">Start ${MODES[profile.settings.difficulty]} →</button>${saved?.rulesVersion===3&&!saved.outcome&&(id!=='puzzle'||saved.puzzleEdition===2)?`<button class="btn" data-ui="resume-game" data-value="${id}">Resume saved ${MODES[saved.difficulty]}</button>`:''}</div><button class="text-button" data-ui="brief-rules" data-value="${id}">Full rules & adaptations ↗</button></div></section></main>`);}
function loadRoute(){let params=new URLSearchParams(location.search),id=params.get('game'),mode=params.get('mode');if(MODES[mode])profile.settings.difficulty=mode;let seed=params.get('seed');if(seed!==null&&/^\d+$/.test(seed)&&Number(seed)<=4294967295)profile.settings.seed=Number(seed);if(ENGINES[id])openBriefing(id,false);else{briefingId=null;library();}}
window.addEventListener('popstate',loadRoute);
function testLink(s){let u=new URL(location.href);u.search=`?game=${s.id}&mode=${s.difficulty}&seed=${s.initialSeed}`;return u.href;}
function feedbackReport(){let s=profile.active;return {edition:3,game:s.id,mode:MODES[s.difficulty],seed:s.initialSeed,round:s.round||s.hand||1,phase:s.phase||'play',clarity:document.getElementById('feedback-clarity').value,difficulty:document.getElementById('feedback-difficulty').value,notes:document.getElementById('feedback-notes').value,replay:testLink(s),recentEvents:s.logs.slice(0,18)};}
function download(value,name){let url=URL.createObjectURL(new Blob([value],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function handleLearningAction(a,v){
if(a==='global-mode'){profile.settings.difficulty=v;let u=new URL(location.href);if(u.searchParams.has('game')){u.searchParams.set('mode',v);history.replaceState({},'',u);}save();if(briefingId)briefing(briefingId);else if(document.querySelector('.game-stage')){game();toast(`${MODES[v]} selected for every new game. This saved match keeps its current mode.`);}else if(screen==='lab')lab();else library();return true;}if(a==='choose-mode'){profile.settings.difficulty=v;let u=new URL(location.href);u.searchParams.set('mode',v);history.replaceState({},'',u);save();briefing(briefingId);return true;}
if(a==='begin-game'){start(v);return true;}
if(a==='resume-game'){let s=JSON.parse(localStorage.getItem(STORE+'.session.'+v));if(s?.rulesVersion===3){profile.active=s;briefingId=null;undoState=null;history.replaceState({},'',testLink(s));save();render();}return true;}
if(a==='brief-rules'){rules(v);return true;}
if(a==='begin-round'){delete profile.active.awaitingRound;resumeActive();save();render();return true;}
if(a==='undo'){if(undoState&&profile.active?.difficulty==='relaxed'){profile.active=undoState;undoState=null;delete profile.active.deadline;save();render();}return true;}
if(a==='lesson'){let l=LESSONS[profile.active.id];openModal(`<span class="eyebrow">WORKED EXAMPLE</span><h2>${GAMES.find(g=>g.id===profile.active.id).name}</h2><p>${esc(l.example)}</p><p>${esc(l.warning)}</p><ol>${l.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`);return true;}
if(a==='test-link'){navigator.clipboard.writeText(testLink(profile.active)).then(()=>toast('Test link copied. It opens this game, mode and starting seed.')).catch(()=>openModal(`<h2>Your test link</h2><p>${esc(testLink(profile.active))}</p>`));return true;}
if(a==='feedback'){openModal(`<span class="eyebrow">HELP REFINE THIS GAME</span><h2>How did this round feel?</h2><label class="field">Instructions<select id="feedback-clarity"><option>Clear</option><option>Somewhat unclear</option><option>I did not know what to do</option></select></label><label class="field">Difficulty<select id="feedback-difficulty"><option>About right</option><option>Too easy</option><option>Too difficult</option></select></label><label class="field">What happened?<textarea id="feedback-notes" rows="5" placeholder="What did you expect? Where did you get stuck?"></textarea></label><p>Includes the game, mode, seed and recent events. Download it or copy it into our chat. Nothing is posted automatically.</p><div class="controls"><button class="btn primary" data-ui="copy-feedback">Copy feedback</button><button class="btn" data-ui="download-feedback">Download report</button></div>`);return true;}
if(a==='copy-feedback'){navigator.clipboard.writeText(JSON.stringify(feedbackReport(),null,2)).then(()=>toast('Feedback copied. Paste it into our chat.')).catch(()=>toast('Use Download report if clipboard access is unavailable.'));return true;}
if(a==='download-feedback'){download(JSON.stringify(feedbackReport(),null,2),'devils-plan-feedback.json');return true;}
return false;
}

document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseActive();else if(document.querySelector('.game-stage')&&!profile.active?.awaitingRound&&!modal.open)resumeActive();});

import {puzzlePlacement} from './puzzle-game.js';
document.addEventListener('mouseover',e=>{let s=profile.active;if(s?.id!=='puzzle'||s.outcome)return;document.querySelectorAll('.puzzle-board .preview-cell,.puzzle-board .invalid-cell').forEach(el=>el.classList.remove('preview-cell','invalid-cell'));let cell=e.target.closest('.puzzle-board .cell');if(!cell)return;let cells=puzzlePlacement(s,+cell.dataset.value);if(cells)for(let i of cells)document.querySelector(`.puzzle-board [data-value="${i}"]`)?.classList.add('preview-cell');else if(s.board[+cell.dataset.value]===-1)cell.classList.add('invalid-cell');});
document.addEventListener('mouseout',e=>{if(e.target.closest('.puzzle-board')&&!e.relatedTarget?.closest?.('.puzzle-board'))document.querySelectorAll('.puzzle-board .preview-cell,.puzzle-board .invalid-cell').forEach(el=>el.classList.remove('preview-cell','invalid-cell'));});
